* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #eef2f6;
  color: #111827;
  font-family: Inter, Arial, sans-serif;
}

.bp-page {
  min-height: 100vh;
  padding: 16px;
}

.toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 110px 96px;
  gap: 10px;
  align-items: end;
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 12px;
  margin-bottom: 12px;
}

.control label {
  display: block;
  margin-bottom: 5px;
  color: #667085;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.control select {
  width: 100%;
  height: 38px;
  border: 1px solid #cfd7e3;
  border-radius: 7px;
  padding: 0 10px;
  background: white;
  color: #111827;
  font-size: 13px;
}

.btn {
  height: 38px;
  border: 0;
  border-radius: 7px;
  background: #dff7e8;
  color: #14532d;
  font-weight: 900;
  cursor: pointer;
}

.btn-dark {
  background: #111827;
  color: white;
}

.bp-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  background: #111827;
  color: white;
  border-radius: 8px;
  padding: 18px;
  margin-bottom: 12px;
}

.eyebrow {
  color: #8ce6c3;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.bp-header h1 {
  margin: 4px 0;
  font-size: 24px;
  line-height: 1.15;
}

.bp-header p {
  margin: 0;
  color: #d1d5db;
  font-size: 12px;
}

.stamp {
  min-width: 190px;
  text-align: right;
  color: #d1d5db;
  font-size: 12px;
}

.stamp strong {
  display: block;
  margin-top: 4px;
  color: white;
}

.stamp small {
  display: block;
  margin-top: 4px;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.kpi {
  background: white;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 13px;
  min-height: 104px;
}

.kpi span {
  display: block;
  color: #667085;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.kpi strong {
  display: block;
  margin-top: 8px;
  color: #111827;
  font-size: 22px;
  font-weight: 900;
  line-height: 1.1;
}

.kpi small {
  display: block;
  margin-top: 8px;
  color: #667085;
  font-size: 11px;
}

.kpi-good {
  border-top: 4px solid #0f766e;
}

.kpi-blue {
  border-top: 4px solid #2563eb;
}

.kpi-warn {
  border-top: 4px solid #b45309;
}

.kpi-bad {
  border-top: 4px solid #b91c1c;
}

.kpi-neutral {
  border-top: 4px solid #475467;
}

.main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(360px, 0.9fr);
  gap: 12px;
}

.card {
  background: white;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 14px;
  min-height: 250px;
}

.card-wide {
  grid-column: span 2;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding-bottom: 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid #e7ecf2;
}

.card-head h2 {
  margin: 0;
  font-size: 15px;
}

.card-head span {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.progress-block {
  margin-bottom: 14px;
}

.progress-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  margin-bottom: 6px;
}

.progress-head span {
  color: #667085;
  font-weight: 800;
}

.track {
  height: 12px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}

.fill {
  height: 100%;
}

.fill-good {
  background: #0f766e;
}

.fill-warn {
  background: #b45309;
}

.fill-bad {
  background: #b91c1c;
}

.metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.metric-grid div {
  border: 1px solid #e7ecf2;
  border-radius: 7px;
  padding: 10px;
  background: #f8fafc;
}

.metric-grid span {
  display: block;
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.metric-grid b {
  display: block;
  margin-top: 6px;
  font-size: 17px;
}

.alert-row,
.list-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid #edf1f5;
}

.alert-row:last-child,
.list-row:last-child {
  border-bottom: 0;
}

.alert-row strong,
.list-row strong {
  display: block;
  color: #111827;
  font-size: 12px;
}

.alert-row span,
.list-row span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 11px;
}

.alert-bad {
  border-left: 4px solid #b91c1c;
  padding-left: 10px;
}

.alert-warn {
  border-left: 4px solid #b45309;
  padding-left: 10px;
}

.right {
  min-width: 96px;
  text-align: right;
  white-space: nowrap;
}

.right b {
  display: block;
}

.right small {
  display: block;
  margin-top: 5px;
  color: #667085;
}

.day-row {
  display: grid;
  grid-template-columns: 150px 1fr 100px;
  gap: 12px;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #edf1f5;
}

.day-row:last-child {
  border-bottom: 0;
}

.day-label strong {
  display: block;
  font-size: 12px;
}

.day-label span {
  display: inline-block;
  margin-top: 4px;
}

.day-bars {
  display: grid;
  gap: 4px;
}

.bar {
  height: 8px;
  border-radius: 999px;
}

.bar.target {
  background: #cbd5e1;
}

.bar.actual {
  background: #0f766e;
}

.day-value {
  text-align: right;
  font-size: 12px;
  font-weight: 900;
}

.positive {
  color: #047857;
}

.negative {
  color: #b91c1c;
}

.badge {
  display: inline-block;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
}

.badge-good {
  background: #dcfce7;
  color: #166534;
}

.badge-warn {
  background: #fef3c7;
  color: #92400e;
}

.badge-bad {
  background: #fee2e2;
  color: #991b1b;
}

.empty {
  padding: 26px 12px;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
  background: #f8fafc;
  color: #667085;
  text-align: center;
  font-size: 12px;
}

@media (max-width: 1180px) {
  .kpis {
    grid-template-columns: repeat(3, 1fr);
  }
  .main-grid {
    grid-template-columns: 1fr;
  }
  .card-wide {
    grid-column: span 1;
  }
}
@media (max-width: 760px) {
  .bp-page {
    padding: 10px;
  }
  .toolbar,
  .kpis,
  .metric-grid {
    grid-template-columns: 1fr;
  }
  .bp-header {
    flex-direction: column;
  }
  .stamp {
    text-align: left;
  }
  .day-row {
    grid-template-columns: 1fr;
  }
  .day-value {
    text-align: left;
  }
}
@media print {
  body {
    background: white;
  }
  .no-print,
  .toolbar {
    display: none !important;
  }
  .bp-page {
    padding: 0;
  }
  .bp-header {
    background: white;
    color: #111827;
    border: 1px solid #111827;
  }
  .bp-header p,
  .stamp,
  .stamp strong {
    color: #111827;
  }
  .eyebrow {
    color: #111827;
  }
  .card,
  .kpi {
    break-inside: avoid;
  }
}

