.main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(360px, .9fr);
  gap: 12px;
}

.card {
  background: white;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 14px;
  min-height: 250px;
}

.card-wide {
  grid-column: span 2;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding-bottom: 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid #e7ecf2;
}

.card-head h2 {
  margin: 0;
  font-size: 15px;
}

.card-head span {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.progress-block {
  margin-bottom: 14px;
}

.progress-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  margin-bottom: 6px;
}

.progress-head span {
  color: #667085;
  font-weight: 800;
}

.track {
  height: 12px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}

.fill {
  height: 100%;
}

.fill-good {
  background: #0f766e;
}

.fill-warn {
  background: #b45309;
}

.fill-bad {
  background: #b91c1c;
}

.metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.metric-grid div {
  border: 1px solid #e7ecf2;
  border-radius: 7px;
  padding: 10px;
  background: #f8fafc;
}

.metric-grid span {
  display: block;
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.metric-grid b {
  display: block;
  margin-top: 6px;
  font-size: 17px;
}

.alert-row,
.list-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid #edf1f5;
}

.alert-row:last-child,
.list-row:last-child {
  border-bottom: 0;
}

.alert-row strong,
.list-row strong {
  display: block;
  color: #111827;
  font-size: 12px;
}

.alert-row span,
.list-row span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 11px;
}

.alert-bad {
  border-left: 4px solid #b91c1c;
  padding-left: 10px;
}

.alert-warn {
  border-left: 4px solid #b45309;
  padding-left: 10px;
}

.right {
  min-width: 96px;
  text-align: right;
  white-space: nowrap;
}

.right b {
  display: block;
}

.right small {
  display: block;
  margin-top: 5px;
  color: #667085;
}

.day-row {
  display: grid;
  grid-template-columns: 150px 1fr 100px;
  gap: 12px;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #edf1f5;
}

.day-row:last-child {
  border-bottom: 0;
}

.day-label strong {
  display: block;
  font-size: 12px;
}

.day-label span {
  display: inline-block;
  margin-top: 4px;
}

.day-bars {
  display: grid;
  gap: 4px;
}

.bar {
  height: 8px;
  border-radius: 999px;
}

.bar.target {
  background: #cbd5e1;
}

.bar.actual {
  background: #0f766e;
}

.day-value {
  text-align: right;
  font-size: 12px;
  font-weight: 900;
}

.positive {
  color: #047857;
}

.negative {
  color: #b91c1c;
}

.badge {
  display: inline-block;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
}

.badge-good {
  background: #dcfce7;
  color: #166534;
}

.badge-warn {
  background: #fef3c7;
  color: #92400e;
}

.badge-bad {
  background: #fee2e2;
  color: #991b1b;
}

.empty {
  padding: 26px 12px;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
  background: #f8fafc;
  color: #667085;
  text-align: center;
  font-size: 12px;
