@media (max-width: 1180px) {
  .kpis {
    grid-template-columns: repeat(3, 1fr);
  }

  .main-grid {
    grid-template-columns: 1fr;
  }

  .card-wide {
    grid-column: span 1;
  }
}

@media (max-width: 760px) {
  .bp-page {
    padding: 10px;
  }

  .toolbar,
  .kpis,
  .metric-grid {
    grid-template-columns: 1fr;
  }

  .bp-header {
    flex-direction: column;
  }

  .stamp {
    text-align: left;
  }

  .day-row {
    grid-template-columns: 1fr;
  }

  .day-value {
    text-align: left;
  }
}

@media print {
  body {
    background: white;
  }

  .no-print,
  .toolbar {
    display: none !important;
  }

  .bp-page {
    padding: 0;
  }

  .bp-header {
    background: white;
    color: #111827;
    border: 1px solid #111827;
  }

  .bp-header p,
  .stamp,
  .stamp strong {
    color: #111827;
  }

  .eyebrow {
    color: #111827;
  }

  .card,
  .kpi {
    break-inside: avoid;
  }
}

