function money(value) {
  return Number(value || 0).toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function num(value) {
  return Number(value || 0).toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function pct(value) {
  return Number(value || 0).toLocaleString("en-GB", {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1
  }) + "%";
}

function safe(value, fallback = "-") {
  return value === null || value === undefined || value === "" ? fallback : String(value);
}

function model() {
  return window.appsmith?.model || {};
}

function controls() {
  const m = model();

  return {
    planId: Number(m.controls?.planId || m.selectedPlan?.planId || m.selectedPlan?.value || 0)
  };
}

async function updateControls(next = {}) {
  const m = model();

  const nextControls = {
    ...controls(),
    ...next
  };

  if (window.appsmith?.updateModel) {
    await window.appsmith.updateModel({
      ...m,
      controls: nextControls
    });
  }

  if (window.appsmith?.triggerEvent) {
    window.appsmith.triggerEvent("onBusinessPlanningChange");
  }
}

function toneByPercent(value) {
  const n = Number(value || 0);

  if (n >= 100) return "good";
  if (n >= 80) return "warn";
  return "bad";
}

function toneByValue(value, inverse = false) {
  const n = Number(value || 0);

  if (inverse) {
    if (n <= 0) return "good";
    if (n < 1000) return "warn";
    return "bad";
  }

  if (n > 0) return "good";
  if (n === 0) return "warn";
  return "bad";
}

function planOptions(m = {}) {
  const current = Number(controls().planId);
  const plans = m.plans || [];

  return plans.map(plan => {
    const value = Number(plan.planId || plan.value || 0);
    return `
      <option value="${value}" ${value === current ? "selected" : ""}>
        ${safe(plan.label || plan.planName)}
      </option>
    `;
  }).join("");
}

function renderToolbar(m = {}) {
  return `
    <section class="toolbar no-print">
      <div class="control">
        <label>Plan</label>
        <select id="planSelect">
          ${planOptions(m)}
        </select>
      </div>

      <button class="btn" id="refreshButton">Refresh</button>
      <button class="btn btn-dark" id="printButton">Print</button>
    </section>
  `;
}

function kpi(label, value, hint, tone = "neutral") {
  return `
    <article class="kpi kpi-${tone}">
      <span>${label}</span>
      <strong>${value}</strong>
      <small>${hint || ""}</small>
    </article>
  `;
}

function progress(label, actual, target, suffix = "EUR") {
  const a = Number(actual || 0);
  const t = Number(target || 0);
  const percent = t === 0 ? 0 : Math.min(140, a / t * 100);
  const tone = toneByPercent(t === 0 ? 0 : a / t * 100);

  return `
    <div class="progress-block">
      <div class="progress-head">
        <span>${label}</span>
        <b>${suffix === "%" ? pct(a) : money(a)} / ${suffix === "%" ? pct(t) : money(t)}</b>
      </div>
      <div class="track">
        <div class="fill fill-${tone}" style="width:${Math.max(2, percent)}%"></div>
      </div>
    </div>
  `;
}

function empty(label) {
  return `<div class="empty">${label}</div>`;
}

function badge(value, tone = "neutral") {
  return `<span class="badge badge-${tone}">${value}</span>`;
}

function renderAlerts(rows = []) {
  if (!rows.length) return empty("No planning alerts");

  return rows.map(row => `
    <div class="alert-row alert-${row.alertType === "SALES_BEHIND" ? "bad" : "warn"}">
      <div>
        <strong>${safe(row.alertType)}</strong>
        <span>${safe(row.alertText)}</span>
      </div>
      <b>${money(row.amountValue)}</b>
    </div>
  `).join("");
}

function renderDailyTrend(rows = []) {
  if (!rows.length) return empty("No daily trend data");

  const max = Math.max(
    ...rows.map(row => Math.max(Number(row.targetAmount || 0), Number(row.actualAmount || 0))),
    1
  );

  return rows.slice(0, 31).map(row => {
    const targetWidth = Math.max(2, Number(row.targetAmount || 0) / max * 100);
    const actualWidth = Math.max(2, Number(row.actualAmount || 0) / max * 100);
    const diff = Number(row.differenceAmount || 0);

    return `
      <div class="day-row">
        <div class="day-label">
          <strong>${safe(row.dayText)}</strong>
          <span>${badge(pct(row.achievementPercent), toneByPercent(row.achievementPercent))}</span>
        </div>
        <div class="day-bars">
          <div class="bar target" style="width:${targetWidth}%"></div>
          <div class="bar actual" style="width:${actualWidth}%"></div>
        </div>
        <div class="day-value ${diff >= 0 ? "positive" : "negative"}">${money(diff)}</div>
      </div>
    `;
  }).join("");
}

function renderBudget(rows = []) {
  if (!rows.length) return empty("No budget lines");

  return rows.map(row => {
    const planned = Number(row.plannedAmount || 0);
    const actual = Number(row.actualAmount || 0);
    const usage = planned === 0 ? 0 : actual / planned * 100;

    return `
      <div class="list-row">
        <div>
          <strong>${safe(row.budgetType)} / ${safe(row.budgetCategory)}</strong>
          <span>Committed ${money(row.committedAmount)} / Remaining ${money(row.remainingAmount)}</span>
        </div>
        <div class="right">
          <b>${money(actual)}</b>
          <small>${pct(usage)}</small>
        </div>
      </div>
    `;
  }).join("");
}

function renderWorkforce(rows = []) {
  if (!rows.length) return empty("No workforce data");

  return rows.slice(0, 12).map(row => `
    <div class="list-row">
      <div>
        <strong>${safe(row.employeeName || row.username)}</strong>
        <span>${safe(row.workDateText)} / ${safe(row.warehouseCode)} / ${safe(row.absenceType, "WORK")}</span>
      </div>
      <div class="right">
        <b>${num(row.actualHours)} h</b>
        <small>Lost ${num(row.lostHours)} h</small>
      </div>
    </div>
  `).join("");
}

function attachEvents() {
  const planSelect = document.getElementById("planSelect");
  const refreshButton = document.getElementById("refreshButton");
  const printButton = document.getElementById("printButton");

  if (planSelect) {
    planSelect.onchange = () => updateControls({ planId: Number(planSelect.value) });
  }

  if (refreshButton) {
    refreshButton.onclick = () => updateControls({});
  }

  if (printButton) {
    printButton.onclick = () => window.print();
  }
}

function render(m = {}) {
  const overview = m.overview || {};
  const alerts = m.alerts || [];
  const dailyTrend = m.dailyTrend || [];
  const budgetUsage = m.budgetUsage || [];
  const workforceImpact = m.workforceImpact || [];

  const achievement = Number(overview.salesAchievementPercent || 0);
  const projected = Number(overview.projectedSales || 0);
  const target = Number(overview.salesTarget || 0);
  const projectionTone = projected >= target ? "good" : "bad";

  const root = document.getElementById("business-planning-root");

  if (!root) return;

  root.innerHTML = `
    <main class="bp-page">
      ${renderToolbar(m)}

      <section class="bp-header">
        <div>
          <div class="eyebrow">Business Planning</div>
          <h1>${safe(overview.planName || m.selectedPlan?.planName, "No plan selected")}</h1>
          <p>${safe(overview.dateFrom)} - ${safe(overview.dateTo)}</p>
        </div>
        <div class="stamp">
          <span>Generated</span>
          <strong>${safe(m.generatedAt)}</strong>
          <small>${safe(m.generatedBy, "")}</small>
        </div>
      </section>

      <section class="kpis">
        ${kpi("Sales Target", money(overview.salesTarget), "Monthly target", "blue")}
        ${kpi("Actual Sales", money(overview.actualSales), pct(achievement) + " achieved", toneByPercent(achievement))}
        ${kpi("Projected Sales", money(overview.projectedSales), "End period projection", projectionTone)}
        ${kpi("Sales Remaining", money(overview.salesRemaining), "Remaining to target", toneByValue(-Number(overview.salesRemaining || 0)))}
        ${kpi("Budget Remaining", money(overview.budgetRemaining), "Budget left", toneByValue(overview.budgetRemaining))}
        ${kpi("Lost Hours", num(overview.lostHours), "Absence impact", Number(overview.lostHours || 0) > 0 ? "warn" : "good")}
      </section>

      <section class="main-grid">
        <article class="card card-wide">
          <div class="card-head">
            <h2>Target Progress</h2>
            <span>${pct(achievement)}</span>
          </div>
          ${progress("Sales", overview.actualSales, overview.salesTarget)}
          ${progress("Margin", overview.actualSales - overview.actualBudgetUsed, overview.marginTarget)}
          ${progress("Budget Used", overview.actualBudgetUsed, overview.budgetAmount)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Planning Alerts</h2>
            <span>${alerts.length}</span>
          </div>
          ${renderAlerts(alerts)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Workforce Impact</h2>
            <span>${num(overview.workforceActualHours)} actual hours</span>
          </div>
          <div class="metric-grid">
            <div><span>Planned hours</span><b>${num(overview.workforcePlannedHours || overview.plannedHours)}</b></div>
            <div><span>Actual hours</span><b>${num(overview.workforceActualHours)}</b></div>
            <div><span>Sick leave</span><b>${num(overview.sickLeaveHours)}</b></div>
            <div><span>Vacation</span><b>${num(overview.vacationHours)}</b></div>
            <div><span>Sales / planned h</span><b>${money(overview.salesPerPlannedHour)}</b></div>
            <div><span>Sales / actual h</span><b>${money(overview.salesPerActualHour)}</b></div>
          </div>
        </article>

        <article class="card card-wide">
          <div class="card-head">
            <h2>Daily Target vs Actual</h2>
            <span>Target and actual by date</span>
          </div>
          ${renderDailyTrend(dailyTrend)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Budget Usage</h2>
            <span>${budgetUsage.length} lines</span>
          </div>
          ${renderBudget(budgetUsage)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>People / Absence Detail</h2>
            <span>${workforceImpact.length} rows</span>
          </div>
          ${renderWorkforce(workforceImpact)}
        </article>
      </section>
    </main>
  `;

  attachEvents();
}

function update(nextModel) {
  render(nextModel || {});
}

if (window.appsmith?.onReady) {
  window.appsmith.onReady(() => {
    render(window.appsmith.model || {});
    window.appsmith.onModelChange(update);
  });
} else {
  render(model());
}
